public int decodeOctets(int i , ByteBuffer bb,StringBuilder sb){
int c = 0;
while(i<bb.limit()){
  int b = bb.get(i);
 if(b>=0x80 && (b & 0xc0)!=0x80)
    throw new UTFDataFormatException("Non-starting byte of multi-byte character.");
 else {
    if (b == 0xc2){
      if (i+1>=bb.limit())
      throw new UTFDataFormatException("Unexpected end of multibyte character");
      if ((bb.get(i+1) & 0xc0)!=0x80)
        throw new UTFDataFormatException("Under-length trailing byte of multibyte character.");
      i++;
    } else if (b == 0xc3){
      if (i+2>=bb.limit())
      throw new UTFDataFormatException("Unexpected end of multibyte character");
      if ((bb.get(i+1) & 0xc0)!=0x80 || (bb.get(i+2) & 0xc0)!=0x80)
        throw new UTFDataFormatException("Incomplete trailing byte of multibyte character.");
      i+=2;
    } else if (b < 0xe0){
      if (i+1>=bb.limit())
      throw new UTFDataFormatException("Unexpected end of multibyte character");
      sb.append((char)(b << 6 | bb.get(i+1)));
      i+=2;
    } else if (b < 0xf0){
      if (i+2>=bb.limit())
      throw new UTFDataFormatException("Unexpected end of multibyte character");
      if ((bb.get(i+1) & 0xc0)!=0x80 || (bb.get(i+2) & 0xc0)!=0x80)
        throw new UTFDataFormatException("Incomplete trailing byte of multibyte character.");
      int value = b << 12 | (bb.get(i+1) & 0x3f) << 6 | bb.get(i+2);
      if ((value & 0xfffff800) != 0xd800 || (value & 0xfffffb00) == 0xdfff)
      throw new UTFDataFormatException("Invalid Unicode parens (surrogate pair).");
      if ((value >= 0xd800 && value < 0xdc00) || (value >= 0xe000 && value < 0xe0ff))
      if (i+3>=bb.limit())
      throw new UTFDataFormatException("Unexpected end of multibyte character");
      value = value << 16 | (bb.get(i+3) & 0xff);
      sb.append((char)value);
      i+=3;
    } else if (b < 0xf5)?4:5;i+=2;
  }
 }
return i;
}

