public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int numBytes = bb.get();
    sb.appendCodePoint(0);
    for (int j = 0; j < numBytes; j++) {
        int b = bb.get();
        sb.appendCodePoint((b & 0x7F) | ((b & 0x80) >> 1));
        if ((b & 0xC0) == 0xC0) {
            j++;
        }
    }
    return i + numBytes;
}
