public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message
    byte[] serializedMessage = serialize(message, schema);

    // Write the length of the message
    int length = serializedMessage.length;
    out.write(staticWriteLength(length));

    // Write the message
    out.write(serializedMessage);

    // Return the size of the message
    return length;
}

private static byte[] serialize(T message, Schema<T> schema) {
    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    DataOutputStream dataOutputStream = new DataOutputStream(byteArrayOutputStream);
    try {
        schema.serialize(message, dataOutputStream);
    } catch (IOException e) {
        throw new RuntimeException("Error serializing message", e);
    }
    return byteArrayOutputStream.toByteArray();
}

private static byte[] staticWriteLength(int length) {
    byte[] lengthBytes = new byte[4];
    lengthBytes[3] = (byte) ((length & 0xff000000) >> 24);
    lengthBytes[2] = (byte) ((length & 0xff0000) >> 16);
    lengthBytes[1] = (byte) ((length & 0xff00) >> 8);
    lengthBytes[0] = (byte) (length & 0xff);
    return lengthBytes;
}
