public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    Type[] parameterTypes = ((ParameterizedType) genericType).getActualTypeArguments();
    List<Class<?>> resolvedArgs = new ArrayList<>(parameterTypes.length);
    for (Type parameterType : parameterTypes) {
        if (parameterType instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) parameterType;
            if (wildcardType.getUpperBound() != null) {
                resolvedArgs.add(targetType);
            } else {
                resolvedArgs.add(Object.class);
            }
        } else if (parameterType instanceof Class<?>) {
            resolvedArgs.add((Class<?>) parameterType);
        }
    }
    return resolvedArgs.toArray(new Class<?>[0]);
}
