public List<TimeRange> buildTimeRanges(long start, long end) {
    if (end - start >= FETCH_DATA_DURATION) {
        return new ArrayList<>();
    }
    List<TimeRange> timeRanges = new ArrayList<>();

    // Each time range should be less than FETCH_DATA_DURATION
    long step = Math.min(FETCH_DATA_DURATION, end - start);
    long currentStart = start;

    while (currentStart < end) {
        timeRanges.add(new TimeRange(currentStart, end));
        currentStart += step;
    }

    return timeRanges;
}
