    long hour = (timeBucket / (1000 * 60 * 60)) % 24;
    long minute = (timeBucket / (1000 * 60)) % 60;
    long second = timeBucket / 1000;

    long compressedDay = (dayStep == 1 ? year : year * 1000 / dayStep) + (dayStep == 2 ? month * 1000 : month * 1000 / dayStep) + (dayStep == 3 ? day * 1000 : day * 1000 / dayStep) + (dayStep == 4 ? hour * 1000 : hour * 1000 / dayStep) + (dayStep == 5 ? minute * 1000 : minute * 1000 / dayStep) + minute * 60;

    return compressedDay * 1000 * 60 * 60 + second;
}
