        throw new IllegalArgumentException("Invalid index or length");
    }

    int count = 0;
    while (index + count < len) {
        int byte1 = (str.charAt(index + count)) & 0xFF;
        if (byte1 < 0xC0) {
            count++;
        } else {
            if (byte1 < 0xE0) {
                count += 2;
            } else if (byte1 < 0xF0) {
                count += 3;
            } else if (byte1 < 0xF8) {
