public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int length = str.length();
    for (int i = 0; i < length; i++) {
        Character c = str.charAt(i);
        if (c == '\u0000') {
            throw new IllegalArgumentException("Null character is not allowed in UTF-8 string");
        } else if (c < '\u0080') {
            lb.put((byte) c);
        } else if (c < '\u00c0') {
            lb.put((byte) ((c >> 6) | 0b11000000));
            lb.put((byte) (c & 0b00111111));
        } else if (c < '\ud800') {
            lb.put((byte) ((c >> 12) | 0b11100000));
            lb.put((byte) ((c >> 6) & 0b00111111));
            lb.put((byte) (c & 0b00001111));
        } else if (c < '\uDC00') {
            if (i + 1 < length && str.charAt(i + 1) >= '\ud800' && str.charAt(i + 1) <= '\udFFF') {
                int unicode = Character.toCodePoint(str.charAt(i), str.charAt(i + 1));
                amountCharactersForInt(unicode);
                lb.put((byte) ((unicode >> 16) | 0b11110000));
                lb.put((byte) ((unicode >> 10) & 0b00111111));
                lb.put((byte) (unicode & 0b00001111));
                i++;
            } else {
                throw new IllegalArgumentException("Composite Unicode character is not allowed in UTF-8 string");
            }
        } else {
            throw new IllegalArgumentException("Invalid Unicode character in UTF-8 string");
        }
    }
    return lb;
}
