public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    ByteBuffer b = lb.getWriterBuffer();
    int len = str.length(), bytesAvailable = b.available(), start = b.position(), lenWritten = 0;
    for(int i = 0; i < len; i++) {
        int c = str.charAt(i);
        if(c < 0x80) { // 7-bit ASCII, just write it
            lenWritten += b.put((byte)c);
        } else if(c < 0xc2 ) { // workaround for UTF-16 two byte sequences by using one byte
            lenWritten += b.put((byte)c);
            lenWritten += b.put((byte)(0xC0 + (c & 0x1F))); // F0 80 - F7 8F
        } else if(c < 0xe0 ) { // 11-bit char, 2 bytes of utf-8
            lenWritten += b.put((byte)c);
            lenWritten += b.put((byte)(0x80 + (c & 0x3F))); // C0 80 - D7 9F
        } else if(c < 0xf0 ) { // 16-bit char, 3 bytes of utf-8
            if(bytesAvailable >= 2) { // Handle high surrogate pairs
                int c2 = str.charAt(++i);
                if ((c & 0xF8) == 0xE0 && (c2 & 0xC0) == 0x80) {
                    lenWritten += b.put((byte)c);
                    lenWritten += b.put((byte)(0x80 + (c & 0x3F)));
                    lenWritten += b.put((byte)(0x80 + (c2 & 0x3F)));
                    start = b.position();
                    while(b.position() < start+2 &&  (b.get() & 0xC0) == 0x80) { // Skip continuation bytes
                        lenWritten += b.get();
                    }
                } else {
                    lenWritten += b.put((byte)c);
                    lenWritten += b.put((byte)(0x80 + (c & 0x1F)));
                }
            }
        } else { // 21-bit char, 4 bytes of utf-8, implementation restricted
            lenWritten += b.put((byte)c);
        }
    }
    lb.setPosition(b.position() - lenWritten);
    return lb;
}
