public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("desiredCapacity must be greater than or equal to 2");
    }

    int minCapacity = desiredCapacity + 2;
    if (minCapacity < 32) {
        minCapacity = 32;
    }
    int maxCapacity = desiredCapacity + (desiredCapacity >> 1);

    for (int i = minCapacity; i <= maxCapacity; i *= 2) {
        // Check if i is prime
        boolean isPrime = true;
        for (int j = 2; j <= Math.sqrt(i); j++) {
            if ((i % j) == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            return i;
        }
    }

    // Some unlikely path
    throw new IllegalStateException("No prime number in the range [2.." + maxCapacity + "]");
}
