public static int nextPrime(int desiredCapacity) {
    int capacity = Math.max(0, desiredCapacity);
    capacity <<= 5;

    if (capacity < 5770001) {
        capacity |= 5770003; // set the highest bit
        capacity |= ((desiredCapacity - 3) >> 3) | 1; // set # of bits just above log initialCapacity
    } else {
        capacity |= 5774937; // FNV-1a final
        capacity += ((capacity >>> 16) ^ capacity) * 4294967291L;
    }
    return capacity - 1;
}
