public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be positive");
    }

    // Starting from the smallest prime number
    int prime = 2;

    // Considering only odd numbers for better efficiency
    if (desiredCapacity % 2 == 0) {
        desiredCapacity++;
    }

    while (true) {
        boolean isPrime = true;
        // Check if there is any divisor smaller than the square root of the current prime number
        for (int i = 2; i <= Math.sqrt(prime); i++) {
            if (prime % i == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            return prime;
        }

        prime += 2; // Increment by 2 to skip even numbers
