public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder writer = new StringBuilder(str.length());
    boolean writeNext = false;
    for(int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if(c == '\\' && writeNext) {
            writer.append(c);
            writeNext = false;
        } else if (c == '\n' || c == '\r') {
            writeNext = true;
            if (c == '\n') {
                writer.append(c);
            }
        } else {
            writeNext = false;
            writer.append(c);
        }
    }
    return writer.toString();
}
