```java
public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder builder = new StringBuilder();
    boolean inEscape = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            inEscape = true;
        } else if (inEscape) {
            switch (c) {
                case 'n':
                    builder.append('\n');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                default:
                    builder.append(c);
                    inEscape = false;
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}
