public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, byteData, position, byteLength);
    } else {
        while (byteLength > 0) {
            byteData[position++] = (byte) 0;
            byteLength--;
        }
    }
    position += byteLength;
    return this;
}
```

```java
public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        this.size += byteLength;
    } else {
        if (this.size + byteLength > this.capacity) {
            byte[] resizedArray = new byte[Math.max(this.capacity * 2, this.size + byteLength)];
            System.arraycopy(this.elements, this.start, resizedArray, 0, this.size);
            this.start = 0;
            this.capacity = resizedArray.length;
            this.elements = resizedArray;
        }
        System.arraycopy(byteArrayValue, byteOffset, this.elements, this.start + this.size, byteLength);
        this.size += byteLength;
    }
    return this;
}
```

