public String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();

    boolean foundTerminator = false;
    for (int i = 0; i < this.getContentSize(); i++) {
        char item = this.getContent().get(i);

        if (foundTerminator) {
            // If found aterminator but next item isn't a terminator, it signifies end
            if (terminators.length == 0 || !Terminators.contains(item)) {
                return token.toString();
            }

            // Reset state if we encountered another terminator really fast
            if (terminators.length == 1 && item == terminators[0]) {
                foundTerminator = false;
                continue;
            }
        }

        // Found a new token
        if (terminators.length == 0 || !Terminators.contains(item)) {
            foundTerminator = true;
            token.append(item);
        }
    }

    return token.toString();
}
