public void moveAllListNodes(DoublyLinkedList<E> list) {
    synchronized (this) {
        ListNode<E> current = list.head;
        while (current != null) {
            ListNode<E> prevElement = current.prev;
            list.removeListNode(current);
            addListNode(list, current);
            current = prevElement;
        }
    }
