public ByteVector putInt(final int intValue) {
    // Check if this byte vector is large enough to hold the integer
    if (position >= vector.length) {
        // Calculate the new size to ensure there's enough space
        int newSize = position + 4;
        // Allocate a new byte array with the increased size
        byte[] newVector = new byte[newSize];
        // Copy the existing data to the new byte array
        System.arraycopy(vector, 0, newVector, 0, position);
        // Set the reference to the new byte array
        vector = newVector;
    }
    // Position at the end of the byte vector
    position += 4;
    // Store the integer in the byte array
    vector[position - 4] = (byte) (intValue >> 24);
    vector[position - 3] = (byte) (intValue >> 16);
    vector[position - 2] = (byte) (intValue >> 8);
    vector[position - 1] = (byte) intValue;
    // Return this byte vector
    return this;
}
