private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    int size = vertices.size();
    if (size < 3) return true; // A graph with less than 3 vertices is always a clique
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false; // Find a vertex that is not connected to any other vertex
            }
        }
    }
    return true; // All vertices are connected to each other
}
