private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    Set<Edge<V, E>> inducedSubgraph = new HashSet<>();
    for (V vertex : vertices) {
        for (V neighbor : graph.neighbors(vertex)) {
            inducedSubgraph.add(graph.getEdge(vertex, neighbor));
        }
    }
    return inducedSubgraph.size() == graph.numNodes();
}
