    if (vertices.isEmpty()) {
        return true;
    }

    Set<V> subgraphVertices = graph.getVertices(vertices);
    if (subgraphVertices.size() != vertices.size()) {
        return false;
    }

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!edgesHas(graph, subgraphVertices, v1, v2)) {
                return false;
            }
        }
    }

    return true;
}
