public static int indexOfExtension(String filename) {
    int lastSeparatorIndex = filename.indexOfLastSeparator();
    if (lastSeparatorIndex == -1) {
        return -1; // No dot found
    } else if (lastSeparatorIndex + 1 < filename.length() && filename.charAt(lastSeparatorIndex + 1) == '/') {
        return -1; // Potential directory separator after the dot
    }
    return lastSeparatorIndex;
}
