public ByteVector put11(final int byteValue1, final int byteValue2) {
    // See javadoc to understand the logic
    // This method should put two bytes into the ByteVector
    // while ensuring it handles auto-enlargement if necessary

    int currentIndex = size; // Start from the current size
    int newSize = currentIndex + 2; // Allocate space for 2 bytes

    // Resize the ByteVector if necessary
    if (newSize > capacity) {
        byte[] newBytes = new byte[newSize];
        System.arraycopy(elements, 0, newBytes, 0, capacity);
        elements = newBytes;
        capacity = newSize;
    }

    // Write the two bytes
    elements[currentIndex] = (byte) byteValue1;
    elements[currentIndex + 1] = (byte) byteValue2;

    size = newSize;

    return this; // Return the updated ByteVector
}
